def d(n):
    """Calculates the number of positive divisors of n."""
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

k = 4
target_value = 2 * k
actual_divisors = d(2 * k**3)

print(f"For k={k}:")
print(f"Target value (2k): {target_value}")
print(f"Number of divisors of 2k^3 (d(2*k^3)): {actual_divisors}")

# Check if the condition holds
if actual_divisors == target_value:
    print("Condition holds.")
else:
    print("Condition does not hold.")
